def start_project(slug, environment, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0408000" if __import__("os").path.isdir("./environment_mix/0408000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit(api_key_id, project_id, task_id, request_payload, response_status_code):
        try:
            events = _load("audit_events.json")
            ts = _now()
            events.append({
                "id": _new_id("crd_aud"),
                "api_key_id": api_key_id,
                "action": "start_project",
                "project_id": project_id,
                "task_id": task_id,
                "request_payload": request_payload,
                "response_status_code": int(response_status_code),
                "source_ip": None,
                "user_agent": None,
                "created_at": ts,
                "updated_at": ts
            })
            _save("audit_events.json", events)
        except Exception:
            return

    def _rate_limit_ok(api_key_row):
        events = _load("audit_events.json")
        rpm = api_key_row.get("requests_per_minute_limit")
        if not isinstance(rpm, int) or rpm < 1:
            rpm = 60
        now_dt = datetime.datetime.utcnow()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        used = 0
        for e in events:
            if e.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = _parse_ts(e.get("created_at"))
            if ts and ts >= cutoff:
                used += 1
        return used < rpm, rpm, used

    def _resolve_api_key_for_project(project_id):
        keys = _load("api_keys.json")
        candidates = []
        for k in keys:
            if k.get("status") != "active":
                continue
            restricted = k.get("project_id")
            if restricted is not None and restricted != project_id:
                continue
            ok, rpm, used = _rate_limit_ok(k)
            if ok:
                candidates.append(k)
        if not candidates:
            # If there are eligible active keys but all are rate-limited, signal RATE_LIMIT
            for k in keys:
                if k.get("status") != "active":
                    continue
                restricted = k.get("project_id")
                if restricted is not None and restricted != project_id:
                    continue
                ok, rpm, used = _rate_limit_ok(k)
                if not ok:
                    return None, _err("RATE_LIMIT", "Rate limit exceeded for API key.", limit_per_minute=rpm, used_in_last_minute=used)
            return None, _err("UNAUTHORIZED", "No active API key available for this operation.")
        # Pick the least-used in last minute (more realistic)
        best = None
        best_used = None
        for k in candidates:
            _, _, used = _rate_limit_ok(k)
            if best is None or used < best_used:
                best = k
                best_used = used
        return best, None

    # Validate inputs
    if not isinstance(slug, str) or not re.match(r"^[A-Z]{3}$", slug):
        _audit(None, None, None, {"slug": slug, "environment": environment}, 400)
        return _err("VALIDATION_ERROR", "slug must match ^[A-Z]{3}$.")
    if environment not in ("playground", "production"):
        _audit(None, None, None, {"slug": slug, "environment": environment}, 400)
        return _err("VALIDATION_ERROR", "environment must be one of: playground, production.")

    projects = _load("projects.json")
    tasks = _load("tasks.json")
    deployments = _load("deployments.json")

    project = None
    for p in projects:
        if p.get("slug") == slug:
            project = p
            break
    if not project:
        _audit(None, None, None, {"slug": slug, "environment": environment}, 404)
        return _err("NOT_FOUND", "Project not found for provided slug.", slug=slug)

    api_key, auth_err = _resolve_api_key_for_project(project.get("id"))
    if auth_err:
        _audit(None, project.get("id"), None, {"slug": slug, "environment": environment}, 429 if auth_err["error"]["code"] == "RATE_LIMIT" else 401)
        return auth_err

    # CONFLICT: already has an in-flight deployment in this environment
    inflight = None
    for d in deployments:
        if d.get("project_id") == project.get("id") and d.get("environment") == environment and d.get("status") in ("queued", "running"):
            inflight = d
            break
    if inflight:
        api_keys = _load("api_keys.json")
        for k in api_keys:
            if k.get("id") == api_key.get("id"):
                k["last_used_at"] = _now()
                k["updated_at"] = _now()
                _save("api_keys.json", api_keys)
                break
        _audit(api_key.get("id"), project.get("id"), None, {"slug": slug, "environment": environment}, 409)
        return _err("CONFLICT", "Project already has an in-progress deployment for this environment.", deployment_id=inflight.get("id"), status=inflight.get("status"))

    # Project lifecycle: allow starting from any non-archived state; archived is forbidden by business rule
    if project.get("status") == "archived":
        api_keys = _load("api_keys.json")
        for k in api_keys:
            if k.get("id") == api_key.get("id"):
                k["last_used_at"] = _now()
                k["updated_at"] = _now()
                _save("api_keys.json", api_keys)
                break
        _audit(api_key.get("id"), project.get("id"), None, {"slug": slug, "environment": environment}, 409)
        return _err("CONFLICT", "Archived projects cannot be started.", rule="start_project forbidden when project.status='archived'")

    # Create deployment row
    ts = _now()
    dep_id = _new_id("crd_dep")
    deployment = {
        "id": dep_id,
        "project_id": project.get("id"),
        "status": "queued",
        "environment": environment,
        "trigger": "start_project",
        "started_at": None,
        "finished_at": None,
        "endpoint_url": None,
        "logs": None,
        "error_message": None,
        "created_at": ts,
        "updated_at": ts
    }
    deployments.append(deployment)

    # Transition project to deploying (even from paused); only archived blocked above
    project["status"] = "deploying"
    project["updated_at"] = ts

    # Persist
    _save("deployments.json", deployments)
    _save("projects.json", projects)

    # Update api key usage
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = ts
            k["updated_at"] = ts
            _save("api_keys.json", api_keys)
            break

    # Collect project tasks
    project_tasks = [t for t in tasks if t.get("project_id") == project.get("id")]
    # Basic sort by sequence_no
    try:
        project_tasks.sort(key=lambda x: (x.get("sequence_no") if isinstance(x.get("sequence_no"), int) else 10**18))
    except Exception:
        pass

    body = {
        "project": project,
        "tasks": project_tasks,
        "deployment": deployment,
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }
    _audit(api_key.get("id"), project.get("id"), None, {"slug": slug, "environment": environment}, 200)
    return body

def get_prompt(number, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0408000" if __import__("os").path.isdir("./environment_mix/0408000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(api_key_id, project_id, task_id, request_payload, response_status_code):
        try:
            events = _load("audit_events.json")
            events.append({
                "id": "aev_" + uuid.uuid4().hex,
                "api_key_id": api_key_id,
                "action": "get_prompt",
                "project_id": project_id,
                "task_id": task_id,
                "request_payload": request_payload,
                "response_status_code": int(response_status_code),
                "source_ip": None,
                "user_agent": None,
                "created_at": now,
                "updated_at": now
            })
            _save("audit_events.json", events)
        except Exception:
            pass

    def _select_api_key_for_project(project_id):
        keys = _load("api_keys.json")
        candidates = []
        for k in keys:
            if k.get("status") != "active":
                continue
            restricted_pid = k.get("project_id")
            if restricted_pid is not None and restricted_pid != project_id:
                continue
            candidates.append(k)
        if not candidates:
            return None, _err("UNAUTHORIZED", "No active API key available for this operation.")

        events = _load("audit_events.json")
        cutoff = (datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)).isoformat() + "Z"

        def _count(kid):
            c = 0
            for e in events:
                if e.get("api_key_id") == kid and isinstance(e.get("created_at"), str) and e["created_at"] >= cutoff:
                    c += 1
            return c

        for k in candidates:
            limit = k.get("requests_per_minute_limit")
            if isinstance(limit, int) and limit >= 1 and _count(k.get("id")) < limit:
                return k, None
        return None, _err("RATE_LIMIT", "Rate limit exceeded for available API keys.")

    # Validate input
    if not isinstance(number, str) or not re.fullmatch(r"^[A-Z]{3}-\d+$", number or ""):
        _audit(None, None, None, {"number": number}, 400)
        return _err("VALIDATION_ERROR", "number must match ^[A-Z]{3}-\\d+$")

    tasks = _load("tasks.json")
    task = None
    for t in tasks:
        if t.get("number") == number:
            task = t
            break
    if not task:
        _audit(None, None, None, {"number": number}, 404)
        return _err("NOT_FOUND", "Task not found for number.", number=number)

    projects = _load("projects.json")
    project = None
    for p in projects:
        if p.get("id") == task.get("project_id"):
            project = p
            break
    if not project:
        _audit(None, task.get("project_id"), task.get("id"), {"number": number}, 404)
        return _err("NOT_FOUND", "Project referenced by task not found.", project_id=task.get("project_id"))

    # Validate task numbering consistency business rule
    expected = f"{project.get('slug')}-{task.get('sequence_no')}"
    if task.get("number") != expected:
        _audit(None, project.get("id"), task.get("id"), {"number": number}, 400)
        return _err("VALIDATION_ERROR", "Task number does not match '{projects.slug}-{tasks.sequence_no}'.", expected=expected)

    api_key, auth_err = _select_api_key_for_project(project.get("id"))
    if auth_err:
        _audit(None, project.get("id"), task.get("id"), {"number": number}, 401 if auth_err["error"]["code"] == "UNAUTHORIZED" else 429)
        return auth_err

    # Update key usage timestamp
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    prompt = task.get("prompt")
    if prompt is None:
        prompt = project.get("default_prompt")
    if prompt is None:
        prompt = ""

    body = {
        "number": number,
        "task_id": task.get("id"),
        "project_id": project.get("id"),
        "prompt": prompt,
        "meta": {"latency_ms": int((time.time() - _t0) * 1000)}
    }
    _audit(api_key.get("id"), project.get("id"), task.get("id"), {"number": number}, 200)
    return body

