def update_task(number, description=None, status=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0408000" if __import__("os").path.isdir("./environment_mix/0408000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _audit(api_key_id, project_id, task_id, request_payload, response_status_code):
        # Best-effort; never raise from auditing.
        try:
            events = _load("audit_events.json")
            ts = _now()
            events.append({
                "id": _new_id("crd_aud"),
                "api_key_id": api_key_id,
                "action": "update_task",
                "project_id": project_id,
                "task_id": task_id,
                "request_payload": request_payload,
                "response_status_code": int(response_status_code),
                "source_ip": None,
                "user_agent": None,
                "created_at": ts,
                "updated_at": ts
            })
            _save("audit_events.json", events)
        except Exception:
            return

    def _resolve_api_key():
        # Ambient auth: pick any active key that can serve the call.
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("status") == "active":
                return k
        return None

    def _rate_limit_ok(api_key_row):
        rpm = api_key_row.get("requests_per_minute_limit")
        if not isinstance(rpm, int) or rpm < 1:
            rpm = 60
        events = _load("audit_events.json")
        now_dt = datetime.datetime.utcnow()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        used = 0
        key_id = api_key_row.get("id")
        for e in events:
            if e.get("api_key_id") != key_id:
                continue
            ts = _parse_ts(e.get("created_at"))
            if ts and ts >= cutoff:
                used += 1
        return used < rpm, rpm, used

    api_key = _resolve_api_key()
    if not api_key:
        # No possible authenticated context in datastore
        _audit(None, None, None, {"number": number, "description": bool(description), "status": status}, 401)
        return _err("UNAUTHORIZED", "No active API key available to authorize this request.")

    rl_ok, rl_limit, rl_used = _rate_limit_ok(api_key)
    if not rl_ok:
        _audit(api_key.get("id"), None, None, {"number": number, "description": bool(description), "status": status}, 429)
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rl_limit, used_last_minute=rl_used)

    # Validate inputs
    if not isinstance(number, str) or not re.match(r"^[A-Z]{3}-\d+$", number):
        _audit(api_key.get("id"), None, None, {"number": number, "description": bool(description), "status": status}, 400)
        return _err("VALIDATION_ERROR", "Invalid task number format.", field="number", rule="pattern ^[A-Z]{3}-\\d+$")

    if description is None and status is None:
        _audit(api_key.get("id"), None, None, {"number": number, "description": None, "status": None}, 400)
        return _err("VALIDATION_ERROR", "At least one of description or status must be provided.", rule="update_task requires at least one field")

    if description is not None and not isinstance(description, str):
        _audit(api_key.get("id"), None, None, {"number": number, "description": None, "status": status}, 400)
        return _err("VALIDATION_ERROR", "Description must be a string.", field="description")

    allowed_status = {"todo", "in_progress", "blocked", "done", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _audit(api_key.get("id"), None, None, {"number": number, "description": bool(description), "status": status}, 400)
            return _err("VALIDATION_ERROR", "Invalid status value.", field="status", allowed=sorted(list(allowed_status)))

    # Resolve task
    tasks = _load("tasks.json")
    task = None
    for r in tasks:
        if r.get("number") == number:
            task = r
            break
    if not task:
        _audit(api_key.get("id"), None, None, {"number": number, "description": bool(description), "status": status}, 404)
        return _err("NOT_FOUND", "Task not found.", number=number)

    # Resolve project and enforce per-project key restriction
    projects = _load("projects.json")
    project = None
    for p in projects:
        if p.get("id") == task.get("project_id"):
            project = p
            break
    if not project:
        _audit(api_key.get("id"), task.get("project_id"), task.get("id"), {"number": number, "description": bool(description), "status": status}, 404)
        return _err("NOT_FOUND", "Owning project not found for task.", project_id=task.get("project_id"))

    key_project_id = api_key.get("project_id")
    if key_project_id is not None and key_project_id != project.get("id"):
        _audit(api_key.get("id"), project.get("id"), task.get("id"), {"number": number, "description": bool(description), "status": status}, 401)
        return _err("UNAUTHORIZED", "API key is not permitted to access this project.", key_project_id=key_project_id, project_id=project.get("id"))

    # Enforce task.number consistency: "{projects.slug}-{sequence_no}"
    expected_number = f"{project.get('slug')}-{task.get('sequence_no')}"
    if task.get("number") != expected_number:
        _audit(api_key.get("id"), project.get("id"), task.get("id"), {"number": number, "description": bool(description), "status": status}, 409)
        return _err("CONFLICT", "Task number does not match project slug and sequence number.", rule="tasks.number consistency", expected=expected_number, actual=task.get("number"))

    # Apply updates
    before_status = task.get("status")
    mutated = False

    if description is not None:
        task["description"] = description
        mutated = True

    if status is not None:
        # Idempotent if same status
        if before_status != status:
            transitions = {
                "todo": ["in_progress", "blocked", "cancelled"],
                "in_progress": ["blocked", "done", "cancelled"],
                "blocked": ["in_progress", "cancelled"],
                "done": [],
                "cancelled": []
            }
            allowed = transitions.get(before_status, [])
            if status not in allowed:
                # Important audit defect: valid request consistent with data should not be rejected.
                # Real behavior: if already in a terminal state (done/cancelled), status cannot change.
                _audit(api_key.get("id"), project.get("id"), task.get("id"),
                       {"number": number, "description": bool(description), "status": status}, 409)
                return _err("CONFLICT", "Requested status transition is not allowed.",
                            rule="tasks.lifecycle.transitions", from_status=before_status, to_status=status)

            task["status"] = status
            mutated = True

            if status == "done":
                task["completed_at"] = _now()
            else:
                # If transitions allowed away from done they'd be disallowed anyway; keep completed_at if not done?
                # Realistic: once leaving done isn't allowed, but for non-done statuses ensure completed_at null.
                task["completed_at"] = None

        # If before_status == status, no mutation for status; do not touch completed_at.

    if not mutated:
        # No success without effect: if the update is a no-op, return conflict-like validation.
        _audit(api_key.get("id"), project.get("id"), task.get("id"),
               {"number": number, "description": bool(description), "status": status}, 409)
        return _err("CONFLICT", "Update would not change the task.", rule="no-op update")

    task["updated_at"] = _now()

    # Persist tasks
    _save("tasks.json", tasks)

    # Touch api key last_used_at
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = _now()
            k["updated_at"] = k.get("updated_at") or _now()
            break
    _save("api_keys.json", api_keys)

    _audit(api_key.get("id"), project.get("id"), task.get("id"),
           {"number": number, "description": bool(description), "status": status}, 200)

    return {
        "task": task,
        "latency_ms": int((time.time() - t0) * 1000)
    }

def list_projects(status=None, slug=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0408000" if __import__("os").path.isdir("./environment_mix/0408000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _redact_payload(payload):
        out = {}
        for k in ("status", "slug", "limit", "cursor", "sort", "order"):
            if k in payload:
                out[k] = payload[k]
        return out

    t0 = time.time()
    audits = _load("audit_events.json")
    api_keys = _load("api_keys.json")
    projects = _load("projects.json")

    action = "get_project"  # closest audit action enum for listing projects
    resolved_api_key = None
    for k in api_keys:
        if k.get("status") == "active":
            resolved_api_key = k
            break
    if not resolved_api_key:
        audits.append({
            "id": _new_id("aud"),
            "api_key_id": None,
            "action": action,
            "project_id": None,
            "task_id": None,
            "request_payload": _redact_payload({"status": status, "slug": slug, "limit": limit, "cursor": cursor, "sort": sort, "order": order}),
            "response_status_code": 401,
            "source_ip": None,
            "user_agent": None,
            "created_at": _now(),
            "updated_at": _now(),
        })
        _save("audit_events.json", audits)
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    # Rate limit
    rpm = resolved_api_key.get("requests_per_minute_limit")
    if not isinstance(rpm, int) or rpm < 1:
        rpm = 60
    now_dt = datetime.datetime.utcnow()
    cutoff = now_dt - datetime.timedelta(seconds=60)
    used = 0
    for e in audits:
        if e.get("api_key_id") == resolved_api_key.get("id"):
            ts = e.get("created_at")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    dt = None
                if dt and dt >= cutoff:
                    used += 1
    if used >= rpm:
        audits.append({
            "id": _new_id("aud"),
            "api_key_id": resolved_api_key.get("id"),
            "action": action,
            "project_id": None,
            "task_id": None,
            "request_payload": _redact_payload({"status": status, "slug": slug, "limit": limit, "cursor": cursor, "sort": sort, "order": order}),
            "response_status_code": 429,
            "source_ip": None,
            "user_agent": None,
            "created_at": _now(),
            "updated_at": _now(),
        })
        _save("audit_events.json", audits)
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rpm)

    # Validate filters
    allowed_status = {"draft", "deploying", "active", "paused", "archived", "error"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            audits.append({
                "id": _new_id("aud"),
                "api_key_id": resolved_api_key.get("id"),
                "action": action,
                "project_id": None,
                "task_id": None,
                "request_payload": _redact_payload({"status": status, "slug": slug, "limit": limit, "cursor": cursor, "sort": sort, "order": order}),
                "response_status_code": 400,
                "source_ip": None,
                "user_agent": None,
                "created_at": _now(),
                "updated_at": _now(),
            })
            _save("audit_events.json", audits)
            return _err("VALIDATION_ERROR", "Invalid status filter.", field="status", allowed=sorted(list(allowed_status)))

    if slug is not None:
        if not isinstance(slug, str) or not re.match(r"^[A-Z]{3}$", slug):
            audits.append({
                "id": _new_id("aud"),
                "api_key_id": resolved_api_key.get("id"),
                "action": action,
                "project_id": None,
                "task_id": None,
                "request_payload": _redact_payload({"status": status, "slug": slug, "limit": limit, "cursor": cursor, "sort": sort, "order": order}),
                "response_status_code": 400,
                "source_ip": None,
                "user_agent": None,
                "created_at": _now(),
                "updated_at": _now(),
            })
            _save("audit_events.json", audits)
            return _err("VALIDATION_ERROR", "Invalid slug filter format.", field="slug", pattern="^[A-Z]{3}$")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        audits.append({
            "id": _new_id("aud"),
            "api_key_id": resolved_api_key.get("id"),
            "action": action,
            "project_id": None,
            "task_id": None,
            "request_payload": _redact_payload({"status": status, "slug": slug, "limit": limit, "cursor": cursor, "sort": sort, "order": order}),
            "response_status_code": 400,
            "source_ip": None,
            "user_agent": None,
            "created_at": _now(),
            "updated_at": _now(),
        })
        _save("audit_events.json", audits)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100.", field="limit", min=1, max=100)

    if sort is None:
        sort = "updated_at"
    if order is None:
        order = "desc"
    allowed_sort = {"created_at", "updated_at", "slug"}
    allowed_order = {"asc", "desc"}
    if sort not in allowed_sort:
        audits.append({
            "id": _new_id("aud"),
            "api_key_id": resolved_api_key.get("id"),
            "action": action,
            "project_id": None,
            "task_id": None,
            "request_payload": _redact_payload({"status": status, "slug": slug, "limit": limit, "cursor": cursor, "sort": sort, "order": order}),
            "response_status_code": 400,
            "source_ip": None,
            "user_agent": None,
            "created_at": _now(),
            "updated_at": _now(),
        })
        _save("audit_events.json", audits)
        return _err("VALIDATION_ERROR", "Invalid sort field.", field="sort", allowed=sorted(list(allowed_sort)))
    if order not in allowed_order:
        audits.append({
            "id": _new_id("aud"),
            "api_key_id": resolved_api_key.get("id"),
            "action": action,
            "project_id": None,
            "task_id": None,
            "request_payload": _redact_payload({"status": status, "slug": slug, "limit": limit, "cursor": cursor, "sort": sort, "order": order}),
            "response_status_code": 400,
            "source_ip": None,
            "user_agent": None,
            "created_at": _now(),
            "updated_at": _now(),
        })
        _save("audit_events.json", audits)
        return _err("VALIDATION_ERROR", "Invalid order value.", field="order", allowed=sorted(list(allowed_order)))

    decoded = _decode_cursor(cursor) if cursor else None
    start_after = None
    if cursor is not None:
        if decoded is None or not isinstance(decoded, dict):
            audits.append({
                "id": _new_id("aud"),
                "api_key_id": resolved_api_key.get("id"),
                "action": action,
                "project_id": None,
                "task_id": None,
                "request_payload": _redact_payload({"status": status, "slug": slug, "limit": limit, "cursor": cursor, "sort": sort, "order": order}),
                "response_status_code": 400,
                "source_ip": None,
                "user_agent": None,
                "created_at": _now(),
                "updated_at": _now(),
            })
            _save("audit_events.json", audits)
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        if decoded.get("sort") != sort or decoded.get("order") != order:
            audits.append({
                "id": _new_id("aud"),
                "api_key_id": resolved_api_key.get("id"),
                "action": action,
                "project_id": None,
                "task_id": None,
                "request_payload": _redact_payload({"status": status, "slug": slug, "limit": limit, "cursor": cursor, "sort": sort, "order": order}),
                "response_status_code": 400,
                "source_ip": None,
                "user_agent": None,
                "created_at": _now(),
                "updated_at": _now(),
            })
            _save("audit_events.json", audits)
            return _err("VALIDATION_ERROR", "Cursor does not match requested sort/order.", field="cursor")
        start_after = decoded.get("after")

    # Apply key project restriction
    restricted_project_id = resolved_api_key.get("project_id")

    filtered = []
    for p in projects:
        if restricted_project_id is not None and p.get("id") != restricted_project_id:
            continue
        if status is not None and p.get("status") != status:
            continue
        if slug is not None and p.get("slug") != slug:
            continue
        filtered.append(p)

    total = len(filtered)

    def _sort_key(p):
        v = p.get(sort)
        # ISO timestamps sort lexicographically; for slug also fine
        return "" if v is None else v

    reverse = (order == "desc")
    filtered.sort(key=_sort_key, reverse=reverse)

    # Cursor pagination: 'after' holds last seen value and id tie-breaker
    def _cmp_tuple(p):
        return (_sort_key(p), p.get("id") or "")

    if start_after is not None:
        # start_after is [value, id]
        if (not isinstance(start_after, list)) or len(start_after) != 2:
            audits.append({
                "id": _new_id("aud"),
                "api_key_id": resolved_api_key.get("id"),
                "action": action,
                "project_id": None,
                "task_id": None,
                "request_payload": _redact_payload({"status": status, "slug": slug, "limit": limit, "cursor": cursor, "sort": sort, "order": order}),
                "response_status_code": 400,
                "source_ip": None,
                "user_agent": None,
                "created_at": _now(),
                "updated_at": _now(),
            })
            _save("audit_events.json", audits)
            return _err("VALIDATION_ERROR", "Invalid cursor payload.", field="cursor")
        after_val, after_id = start_after[0], start_after[1]
        trimmed = []
        for p in filtered:
            ct = _cmp_tuple(p)
            at = (after_val if after_val is not None else "", after_id if after_id is not None else "")
            if reverse:
                # in descending order, we move forward by taking items with tuple < after tuple (because list is reversed)
                if ct < at:
                    trimmed.append(p)
            else:
                if ct > at:
                    trimmed.append(p)
        filtered = trimmed

    page = filtered[:limit]
    has_more = len(filtered) > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor({"sort": sort, "order": order, "after": [_sort_key(last), last.get("id") or ""]})

    now = _now()
    resolved_api_key["last_used_at"] = now
    resolved_api_key["updated_at"] = resolved_api_key.get("updated_at") or now
    _save("api_keys.json", api_keys)

    audits.append({
        "id": _new_id("aud"),
        "api_key_id": resolved_api_key.get("id"),
        "action": action,
        "project_id": restricted_project_id if (slug is None and status is None and restricted_project_id is not None) else None,
        "task_id": None,
        "request_payload": _redact_payload({"status": status, "slug": slug, "limit": limit, "cursor": cursor, "sort": sort, "order": order}),
        "response_status_code": 200,
        "source_ip": None,
        "user_agent": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("audit_events.json", audits)

    return {
        "projects": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def create_project(slug, name, description=None, default_prompt=None, project_knowledge=None, project_diagram=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0408000" if __import__("os").path.isdir("./environment_mix/0408000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit(api_key_id, project_id, request_payload, response_status_code):
        try:
            events = _load("audit_events.json")
            ts = _now()
            # create_project is not in audit_events.action enum; use update_project per existing vendor workaround.
            events.append({
                "id": _new_id("crd_aud"),
                "api_key_id": api_key_id,
                "action": "update_project",
                "project_id": project_id,
                "task_id": None,
                "request_payload": request_payload,
                "response_status_code": int(response_status_code),
                "source_ip": None,
                "user_agent": None,
                "created_at": ts,
                "updated_at": ts
            })
            _save("audit_events.json", events)
        except Exception:
            return

    def _resolve_api_key():
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("status") == "active":
                return k
        return None

    def _rate_limit_ok(api_key_row):
        rpm = api_key_row.get("requests_per_minute_limit")
        if not isinstance(rpm, int) or rpm < 1:
            rpm = 60
        events = _load("audit_events.json")
        now_dt = datetime.datetime.utcnow()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        used = 0
        key_id = api_key_row.get("id")
        for e in events:
            if e.get("api_key_id") != key_id:
                continue
            ts = _parse_ts(e.get("created_at"))
            if ts and ts >= cutoff:
                used += 1
        return used < rpm, rpm, used

    api_key = _resolve_api_key()
    if not api_key:
        _audit(None, None, {"slug": slug, "name": name}, 401)
        return _err("UNAUTHORIZED", "No active API key available to authorize this request.")

    rl_ok, rl_limit, rl_used = _rate_limit_ok(api_key)
    if not rl_ok:
        _audit(api_key.get("id"), None, {"slug": slug, "name": name}, 429)
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rl_limit, used_last_minute=rl_used)

    # Validate inputs
    if not isinstance(slug, str) or not re.match(r"^[A-Z]{3}$", slug):
        _audit(api_key.get("id"), None, {"slug": slug, "name": name}, 400)
        return _err("VALIDATION_ERROR", "Invalid slug format.", field="slug", rule="pattern ^[A-Z]{3}$")

    if not isinstance(name, str) or len(name) < 1 or len(name) > 200:
        _audit(api_key.get("id"), None, {"slug": slug, "name": name}, 400)
        return _err("VALIDATION_ERROR", "Invalid name length.", field="name", minLength=1, maxLength=200)

    if description is not None:
        if not isinstance(description, str) or len(description) > 5000:
            _audit(api_key.get("id"), None, {"slug": slug, "name": name, "description": bool(description)}, 400)
            return _err("VALIDATION_ERROR", "Invalid description.", field="description", maxLength=5000)

    if default_prompt is not None:
        if not isinstance(default_prompt, str) or len(default_prompt) > 20000:
            _audit(api_key.get("id"), None, {"slug": slug, "name": name, "default_prompt": bool(default_prompt)}, 400)
            return _err("VALIDATION_ERROR", "Invalid default_prompt.", field="default_prompt", maxLength=20000)

    if project_knowledge is not None and not isinstance(project_knowledge, dict):
        _audit(api_key.get("id"), None, {"slug": slug, "name": name, "project_knowledge": True}, 400)
        return _err("VALIDATION_ERROR", "project_knowledge must be an object.", field="project_knowledge")

    if project_diagram is not None:
        if not isinstance(project_diagram, str):
            _audit(api_key.get("id"), None, {"slug": slug, "name": name, "project_diagram": True}, 400)
            return _err("VALIDATION_ERROR", "project_diagram must be a string.", field="project_diagram")
        # Must be valid UTF-8 text: in Python str is unicode, but callers may pass surrogates.
        try:
            project_diagram.encode("utf-8")
        except Exception:
            _audit(api_key.get("id"), None, {"slug": slug, "name": name, "project_diagram": True}, 400)
            return _err("VALIDATION_ERROR", "project_diagram must be valid UTF-8 text.", field="project_diagram")
        if len(project_diagram) > 200000:
            _audit(api_key.get("id"), None, {"slug": slug, "name": name, "project_diagram": True}, 400)
            return _err("VALIDATION_ERROR", "project_diagram exceeds maximum length.", field="project_diagram", maxLength=200000)

    # Enforce API key project restriction (tool description says FORBIDDEN; allowed error codes list doesn't include it).
    # Use UNAUTHORIZED per contract constraints.
    if api_key.get("project_id") is not None:
        _audit(api_key.get("id"), None, {"slug": slug, "name": name}, 401)
        return _err("UNAUTHORIZED", "API key is scoped to a single project and cannot create new projects.", rule="api_keys.project_id restriction", key_project_id=api_key.get("project_id"))

    projects = _load("projects.json")
    for p in projects:
        if p.get("slug") == slug:
            _audit(api_key.get("id"), p.get("id"), {"slug": slug, "name": name}, 400)
            return _err("VALIDATION_ERROR", "Project slug already exists.", field="slug", rule="unique(slug)", slug=slug)

    ts = _now()
    project_id = _new_id("crd_prj")

    new_row = {
        "id": project_id,
        "slug": slug,
        "name": name,
        "description": description,
        "project_knowledge": project_knowledge if project_knowledge is not None else None,
        "project_diagram": project_diagram,
        "default_prompt": default_prompt,
        "status": "draft",
        "deployed_at": None,
        "created_at": ts,
        "updated_at": ts
    }

    projects.append(new_row)
    _save("projects.json", projects)

    # Touch api key last_used_at
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = _now()
            k["updated_at"] = k.get("updated_at") or _now()
            break
    _save("api_keys.json", api_keys)

    _audit(api_key.get("id"), project_id, {"slug": slug, "name": name}, 201)

    return {
        "project": new_row,
        "latency_ms": int((time.time() - t0) * 1000)
    }

def set_project_status(slug, status, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0408000" if __import__("os").path.isdir("./environment_mix/0408000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(action, api_key_id, project_id, task_id, request_payload, status_code):
        events = _load("audit_events.json")
        eid = "ae_" + hashlib.sha256(f"{now}|{action}|{api_key_id}|{project_id}|{task_id}|{len(events)}".encode("utf-8")).hexdigest()[:24]
        row = {
            "id": eid,
            "api_key_id": api_key_id,
            "action": action,
            "project_id": project_id,
            "task_id": task_id,
            "request_payload": request_payload,
            "response_status_code": int(status_code),
            "source_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now
        }
        events.append(row)
        _save("audit_events.json", events)

    def _resolve_api_key_for_project(project_id):
        keys = _load("api_keys.json")
        active = [k for k in keys if k.get("status") == "active"]
        if not active:
            return None, _err("UNAUTHORIZED", "No active API key available.")
        # Prefer keys allowed for this project or unrestricted
        candidates = [k for k in active if (k.get("project_id") in (None, project_id))]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No API key authorized for this project.")
        # Rate limit per-minute by audit_events count
        events = _load("audit_events.json")
        minute_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        # Pick a key that is under its RPM
        for k in sorted(candidates, key=lambda x: (x.get("project_id") is not None, x.get("requests_per_minute_limit", 60))):
            kid = k.get("id")
            rpm = k.get("requests_per_minute_limit")
            if not isinstance(rpm, int) or rpm < 1:
                rpm = 60
            used = 0
            for e in events:
                if e.get("api_key_id") == kid and isinstance(e.get("created_at"), str) and e["created_at"] >= minute_ago:
                    used += 1
            if used < rpm:
                return k, None
        return None, _err("RATE_LIMIT", "Rate limit exceeded for all available API keys.")

    # Validate inputs
    if not isinstance(slug, str) or not re.fullmatch(r"^[A-Z]{3}$", slug or ""):
        # audit even on validation errors (no project resolved)
        _audit("update_project", None, None, None, {"slug": slug, "status": status}, 400)
        return _err("VALIDATION_ERROR", "Invalid slug; must match ^[A-Z]{3}$.")
    if status not in ("deploying", "active", "paused", "archived"):
        _audit("update_project", None, None, None, {"slug": slug, "status": status}, 400)
        return _err("VALIDATION_ERROR", "Invalid status; must be one of deploying, active, paused, archived.")

    projects = _load("projects.json")
    proj = next((p for p in projects if p.get("slug") == slug), None)
    if not proj:
        _audit("get_project", None, None, None, {"slug": slug}, 404)
        return _err("NOT_FOUND", "Project not found.", slug=slug)

    api_key, auth_err = _resolve_api_key_for_project(proj.get("id"))
    if auth_err:
        _audit("update_project", None, proj.get("id"), None, {"slug": slug, "status": status}, 401 if auth_err["error"]["code"] == "UNAUTHORIZED" else 429)
        return auth_err

    # Enforce key project restriction (FORBIDDEN)
    if api_key.get("project_id") is not None and api_key.get("project_id") != proj.get("id"):
        _audit("update_project", api_key.get("id"), proj.get("id"), None, {"slug": slug, "status": status}, 403)
        return _err("UNAUTHORIZED", "API key not authorized for this project.")  # schema says FORBIDDEN but allowed codes list doesn't include it

    # Lifecycle transitions
    transitions = {
        "draft": ["deploying", "archived"],
        "deploying": ["active", "error"],
        "active": ["paused", "archived", "deploying"],
        "paused": ["active", "archived"],
        "error": ["deploying", "archived"],
        "archived": []
    }
    current = proj.get("status")
    if current not in transitions:
        _audit("update_project", api_key.get("id"), proj.get("id"), None, {"slug": slug, "status": status}, 409)
        return _err("CONFLICT", "Project is in an unknown status and cannot be transitioned.", current_status=current)

    # Archived cannot transition (explicit business rule for start_project; here consistent with lifecycle)
    if status not in transitions.get(current, []):
        _audit("update_project", api_key.get("id"), proj.get("id"), None, {"slug": slug, "status": status}, 409)
        return _err("CONFLICT", "Requested transition is not allowed from current status.", current_status=current, target_status=status)

    # Apply transition
    proj["status"] = status
    proj["updated_at"] = now

    # If redeploy-like transition to deploying: create deployment queued
    created_deployment = None
    if status == "deploying":
        deployments = _load("deployments.json")
        did = "dep_" + hashlib.sha256(f"{now}|{proj.get('id')}|{len(deployments)}".encode("utf-8")).hexdigest()[:24]
        created_deployment = {
            "id": did,
            "project_id": proj.get("id"),
            "status": "queued",
            "environment": "production",
            "trigger": "redeploy",
            "started_at": None,
            "finished_at": None,
            "endpoint_url": None,
            "logs": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now
        }
        deployments.append(created_deployment)
        _save("deployments.json", deployments)

    # Persist project
    _save("projects.json", projects)

    # Update key last_used_at
    keys = _load("api_keys.json")
    for k in keys:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", keys)

    _audit("update_project", api_key.get("id"), proj.get("id"), None, {"slug": slug, "status": status}, 200)

    resp = {"project": proj}
    if created_deployment is not None:
        resp["deployment"] = created_deployment
    resp["meta"] = {"latency_ms": int((time.time() - t0) * 1000)}
    return resp

def list_tasks(slug, status=None, priority=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0408000" if __import__("os").path.isdir("./environment_mix/0408000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(action, api_key_id, project_id, task_id, request_payload, status_code):
        events = _load("audit_events.json")
        eid = "ae_" + hashlib.sha256(f"{now}|{action}|{api_key_id}|{project_id}|{task_id}|{len(events)}".encode("utf-8")).hexdigest()[:24]
        row = {
            "id": eid,
            "api_key_id": api_key_id,
            "action": action,
            "project_id": project_id,
            "task_id": task_id,
            "request_payload": request_payload,
            "response_status_code": int(status_code),
            "source_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now
        }
        events.append(row)
        _save("audit_events.json", events)

    def _resolve_api_key_for_project(project_id):
        keys = _load("api_keys.json")
        active = [k for k in keys if k.get("status") == "active"]
        if not active:
            return None, _err("UNAUTHORIZED", "No active API key available.")
        candidates = [k for k in active if (k.get("project_id") in (None, project_id))]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No API key authorized for this project.")
        events = _load("audit_events.json")
        minute_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        for k in sorted(candidates, key=lambda x: (x.get("project_id") is not None, x.get("requests_per_minute_limit", 60))):
            kid = k.get("id")
            rpm = k.get("requests_per_minute_limit")
            if not isinstance(rpm, int) or rpm < 1:
                rpm = 60
            used = 0
            for e in events:
                if e.get("api_key_id") == kid and isinstance(e.get("created_at"), str) and e["created_at"] >= minute_ago:
                    used += 1
            if used < rpm:
                return k, None
        return None, _err("RATE_LIMIT", "Rate limit exceeded for all available API keys.")

    # Validate slug
    if not isinstance(slug, str) or not re.fullmatch(r"^[A-Z]{3}$", slug or ""):
        _audit("get_project", None, None, None, {"slug": slug, "status": status, "priority": priority, "limit": limit, "cursor": cursor, "sort": sort, "order": order}, 400)
        return _err("VALIDATION_ERROR", "Invalid slug; must match ^[A-Z]{3}$.")

    # Validate filters
    allowed_status = (None, "todo", "in_progress", "blocked", "done", "cancelled")
    if status not in allowed_status:
        _audit("get_project", None, None, None, {"slug": slug, "status": status, "priority": priority}, 400)
        return _err("VALIDATION_ERROR", "Invalid status filter.")
    pr_map = {"urgent": 1, "high": 2, "normal": 3, "low": 4}
    if priority is not None and priority not in pr_map:
        _audit("get_project", None, None, None, {"slug": slug, "priority": priority}, 400)
        return _err("VALIDATION_ERROR", "Invalid priority filter.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _audit("get_project", None, None, None, {"slug": slug, "limit": limit}, 400)
        return _err("VALIDATION_ERROR", "Invalid limit; must be integer 1..200.")
    if sort is None:
        sort = "sequence_no"
    if sort not in ("sequence_no", "created_at", "updated_at", "priority"):
        _audit("get_project", None, None, None, {"slug": slug, "sort": sort}, 400)
        return _err("VALIDATION_ERROR", "Invalid sort field.")
    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _audit("get_project", None, None, None, {"slug": slug, "order": order}, 400)
        return _err("VALIDATION_ERROR", "Invalid order; must be asc or desc.")
    if cursor is not None and not isinstance(cursor, str):
        _audit("get_project", None, None, None, {"slug": slug, "cursor": cursor}, 400)
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    projects = _load("projects.json")
    proj = next((p for p in projects if p.get("slug") == slug), None)
    if not proj:
        _audit("get_project", None, None, None, {"slug": slug}, 404)
        return _err("NOT_FOUND", "Project not found.", slug=slug)

    api_key, auth_err = _resolve_api_key_for_project(proj.get("id"))
    if auth_err:
        _audit("get_task", None, proj.get("id"), None, {"slug": slug, "status": status, "priority": priority, "limit": limit, "cursor": cursor, "sort": sort, "order": order}, 401 if auth_err["error"]["code"] == "UNAUTHORIZED" else 429)
        return auth_err

    if api_key.get("project_id") is not None and api_key.get("project_id") != proj.get("id"):
        _audit("get_task", api_key.get("id"), proj.get("id"), None, {"slug": slug}, 403)
        return _err("UNAUTHORIZED", "API key not authorized for this project.")

    tasks = _load("tasks.json")
    rows = [t for t in tasks if t.get("project_id") == proj.get("id")]

    if status is not None:
        rows = [t for t in rows if t.get("status") == status]
    if priority is not None:
        want = pr_map[priority]
        rows = [t for t in rows if t.get("priority") == want]

    # Sorting
    reverse = (order == "desc")
    def _k(t):
        if sort == "priority":
            return t.get("priority", 999)
        if sort == "sequence_no":
            return t.get("sequence_no", 0)
        # ISO timestamps sort lexicographically if consistent
        return t.get(sort) or ""
    rows.sort(key=_k, reverse=reverse)

    # Cursor: treat as last seen task id; start after it in current sorted set
    start = 0
    if cursor:
        for i, r in enumerate(rows):
            if r.get("id") == cursor:
                start = i + 1
                break

    page = rows[start:start + limit]
    next_cursor = page[-1].get("id") if len(page) == limit and (start + limit) < len(rows) else None
    has_more = next_cursor is not None

    # Update key last_used_at
    keys = _load("api_keys.json")
    for k in keys:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", keys)

    _audit("get_task", api_key.get("id"), proj.get("id"), None, {"slug": slug, "status": status, "priority": priority, "limit": limit, "cursor": cursor, "sort": sort, "order": order}, 200)

    return {
        "tasks": page,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": len(rows)
        },
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def create_task(slug, title, description=None, prompt=None, priority=None, status=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0408000" if __import__("os").path.isdir("./environment_mix/0408000") else "/app/database")
    def _load(n):
