            "task_id": task_id,
            "request_payload": request_payload,
            "response_status_code": int(status_code),
            "source_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now
        }
        events.append(row)
        _save("audit_events.json", events)

    def _resolve_api_key_for_project(project_id):
        keys = _load("api_keys.json")
        active = [k for k in keys if k.get("status") == "active"]
        if not active:
            return None, _err("UNAUTHORIZED", "No active API key available.")
        candidates = [k for k in active if (k.get("project_id") in (None, project_id))]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No API key authorized for this project.")
        events = _load("audit_events.json")
        minute_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        for k in sorted(candidates, key=lambda x: (x.get("project_id") is not None, x.get("requests_per_minute_limit", 60))):
            kid = k.get("id")
            rpm = k.get("requests_per_minute_limit")
            if not isinstance(rpm, int) or rpm < 1:
                rpm = 60
            used = 0
            for e in events:
                if e.get("api_key_id") == kid and isinstance(e.get("created_at"), str) and e["created_at"] >= minute_ago:
                    used += 1
            if used < rpm:
                return k, None
        return None, _err("RATE_LIMIT", "Rate limit exceeded for all available API keys.")

    # Validate slug/title
    if not isinstance(slug, str) or not re.fullmatch(r"^[A-Z]{3}$", slug or ""):
        _audit("update_task", None, None, None, {"slug": slug, "title": title}, 400)
        return _err("VALIDATION_ERROR", "Invalid slug; must match ^[A-Z]{3}$.")
    if not isinstance(title, str) or not (1 <= len(title) <= 300):
        _audit("update_task", None, None, None, {"slug": slug, "title": title}, 400)
        return _err("VALIDATION_ERROR", "Invalid title; must be 1..300 characters.")
    if description is not None:
        if not isinstance(description, str) or len(description) > 20000:
            _audit("update_task", None, None, None, {"slug": slug, "description": None if description is None else "REDACTED_TOO_LARGE"}, 400)
            return _err("VALIDATION_ERROR", "Invalid description; must be <= 20000 characters.")
    if prompt is not None:
        if not isinstance(prompt, str) or len(prompt) > 20000:
            _audit("update_task", None, None, None, {"slug": slug, "prompt": None if prompt is None else "REDACTED_TOO_LARGE"}, 400)
            return _err("VALIDATION_ERROR", "Invalid prompt; must be <= 20000 characters.")
    pr_map = {"urgent": 1, "high": 2, "normal": 3, "low": 4}
    if priority is None:
        priority = "normal"
    if priority not in pr_map:
        _audit("update_task", None, None, None, {"slug": slug, "priority": priority}, 400)
        return _err("VALIDATION_ERROR", "Invalid priority; must be low, normal, high, urgent.")
    if status is None:
        status = "todo"
    if status not in ("todo", "in_progress", "blocked"):
        _audit("update_task", None, None, None, {"slug": slug, "status": status}, 400)
        return _err("VALIDATION_ERROR", "Invalid initial status; must be todo, in_progress, or blocked.")

    projects = _load("projects.json")
    proj = next((p for p in projects if p.get("slug") == slug), None)
    if not proj:
        _audit("get_project", None, None, None, {"slug": slug}, 404)
        return _err("NOT_FOUND", "Project not found.", slug=slug)

    api_key, auth_err = _resolve_api_key_for_project(proj.get("id"))
    if auth_err:
        _audit("update_task", None, proj.get("id"), None, {"slug": slug, "title": title, "priority": priority, "status": status}, 401 if auth_err["error"]["code"] == "UNAUTHORIZED" else 429)
        return auth_err

    if api_key.get("project_id") is not None and api_key.get("project_id") != proj.get("id"):
        _audit("update_task", api_key.get("id"), proj.get("id"), None, {"slug": slug}, 403)
        return _err("UNAUTHORIZED", "API key not authorized for this project.")

    if proj.get("status") == "archived":
        _audit("update_task", api_key.get("id"), proj.get("id"), None, {"slug": slug, "title": title}, 409)
        return _err("CONFLICT", "Cannot create tasks under an archived project.", project_status="archived")

    tasks = _load("tasks.json")

    # sequence_no unique per project: pick max+1
    max_seq = 0
    for t in tasks:
        if t.get("project_id") == proj.get("id"):
            sn = t.get("sequence_no")
            if isinstance(sn, int) and sn > max_seq:
                max_seq = sn
    sequence_no = max_seq + 1
    number = f"{slug}-{sequence_no}"

    # Enforce global unique(number) and per-project unique(sequence_no)
    if any(t.get("number") == number for t in tasks):
        _audit("update_task", api_key.get("id"), proj.get("id"), None, {"slug": slug, "title": title}, 409)
        return _err("CONFLICT", "Task number already exists.", number=number)
    if any(t.get("project_id") == proj.get("id") and t.get("sequence_no") == sequence_no for t in tasks):
        _audit("update_task", api_key.get("id"), proj.get("id"), None, {"slug": slug, "title": title}, 409)
        return _err("CONFLICT", "Task sequence number already exists in project.", sequence_no=sequence_no)

    tid = "tsk_" + hashlib.sha256(f"{now}|{proj.get('id')}|{sequence_no}|{len(tasks)}".encode("utf-8")).hexdigest()[:24]
    task = {
        "id": tid,
        "project_id": proj.get("id"),
        "sequence_no": sequence_no,
        "number": number,
        "title": title,
        "description": description,
        "prompt": prompt,
        "status": status,
        "priority": pr_map[priority],
        "created_at": now,
        "updated_at": now,
        "completed_at": None
    }

    tasks.append(task)
    _save("tasks.json", tasks)

    # Update key last_used_at
    keys = _load("api_keys.json")
    for k in keys:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", keys)

    _audit("update_task", api_key.get("id"), proj.get("id"), tid, {"slug": slug, "title": title, "description": ("REDACTED" if description else None), "prompt": ("REDACTED" if prompt else None), "priority": priority, "status": status}, 201)

    return {
        "task": task,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }
